INSERT INTO `imgrecords` VALUES (1046, 'http://127.0.0.1:9999/files/2abc810ea1c8456489907a66069e2bd7_隐患1.png', 'http://127.0.0.1:9999/files/0bc0e31998da41e0ace0a4b22f880e03_result.jpg', '[\"0.58\",\"0.55\",\"0.47\"]', '48.51秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 17:21:58', '[\"未穿反光背心\",\"未佩戴安全帽\",\"机械违规作业\"]', NULL, '检测到 3 项隐患：未穿反光背心、未佩戴安全帽、机械违规作业。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的人员必须正确佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场出入口、基坑周边、吊装作业区等危险区域作业人员必须穿着符合GB20653规定的橙色或黄色高可视性反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或雾天辨识失效，可能引发重伤事故）\n\n整改建议：立即停止该人员相关作业，责令穿戴合格反光背心后方可复工；对当日所有在场作业人员开展反光背心佩戴情况全覆盖排查。\n\n处理方法：按项目安全管理制度进行登记扣分；首次违规予以口头警告并记录；重复违规须停工再教育并纳入班组考核。\n\n预防措施：①将反光背心纳入劳保用品发放台账，实行“一人一卡、领用签字、定期更换”；②在工地出入口设置反光背心强制穿戴提示牌及自助领取点；③每日班前教育强调高风险区域（如场内运输通道、塔吊覆盖区）必须全程穿戴；④安全员采用“四不两直”方式开展随机抽查，结果与分包单位履约评价挂钩。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的所有人员必须佩戴安全帽，并在存在车辆通行、夜间或能见度不良区域作业时，必须穿着符合GB 20653—2006《职业用高可视性警示服》规定的反光背心（或高可视性服装）。”  \n风险等级：中风险（易导致车辆碰撞、机械伤害、误入危险作业区等事故）  \n整改建议：立即停止相关区域作业，对未穿戴人员进行现场纠正并登记...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.2条、《建设工程安全生产管理条例》第二十七条及《建筑施工个人防护用品使用管理规范》（JGJ184-2009）第4.1.1条：  \n风险等级：高风险（易导致颅脑损伤，属可记录伤害及以上事件）；  \n整改建议：立即停止该人员作业，清退出施工现场，待完成安全教育并考核合格后方可复工；  \n处理方法：对当事人进行书面警告并登记违章记录；班组长及安全员现场训诫，组织全体人员开展“未戴安全帽事故案例”警示教育；  \n预防措施：实行“进门即查、上岗必检”制度，设置智能门禁+AI视频识别系统自动抓拍未佩戴行为；将安全帽纳入实名制劳保发放台账，绑定身份证号与领用记录；每日班前会强调PPE强制佩戴要求，并由安全员逐人检查确认。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.1.3条，以及《建筑施工安全检查标准》JGJ 59-2011 表3.0.3（安全管理检查评分表）第2项强制性条款：进入施工现场的所有人员必须正确佩戴安全帽。\n\n风险等级：Ⅰ级（重大风险，属“一票否决”项，可直接导致高处坠落物打击致死/重伤...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：机械违规作业\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工安全检查标准》（JGJ59-2011）第3.1.3条、第3.17条及《建设工程安全生产管理条例》第二十七条，机械违规作业属**重大风险等级**（可能导致群死群伤或设备倾覆、吊物坠落等严重事故）。  \n\n**整改建议**：立即停止违规作业，撤出危险区域人员，对涉事机械停用并挂牌标识“禁止操作”。  \n\n**处理方法**：  \n① 由项目安全负责人牵头组织专项排查，核查操作人员持证情况、机械备案与检测合格证明、作业方案审批及交底记录；  \n② 对无证操作、超载吊装、斜拉歪吊、带病运行等行为，按《JGJ59-2011》表B.17“起重吊装检查评分表”逐项扣分，并依据企业安全管理制度追责；  \n③ 涉及特种设备的，须报属地住建部门及市场监管部门联合复检后方可复工。  \n\n**预防措施**：  \n① 严格执行“一机一档”管理，确保设备定期维保、检验合格、限位保险装置齐全有效；  \n② 落实“人机双准入”制度——操作人员须持有效特种作业操作证+项目部安全考核合格证，机械须经进场验收+每日班前试运行；  \n③ 推行可视化交底与AI视频监控联动，对吊装、挖机回转半径、塔吊覆盖区等高风险作业实施全过程旁站监督。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.18.3条（起重机械）及第3.19.3条（施工机具），机械违规作业属**重大风险等级**（Ⅰ级风险）。  \n整改建议：立即停止作业，撤出操作人员，对违规机械进行停用封存。  \n处理方法：由持证特种作业人员（如安拆工、司机、信号司索工）联合设备管理工程师开展全面排查；核查设备备案、检测合格证、维保记录及作业方案审批情况；对无证操作、超载、斜拉...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1047, 'http://127.0.0.1:9999/files/2abc810ea1c8456489907a66069e2bd7_隐患1.png', 'http://127.0.0.1:9999/files/7e9947e9d8c144c981c5917eec1fd17d_result.jpg', '[\"0.58\",\"0.55\",\"0.47\"]', '44.69秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 17:37:34', '[\"未穿反光背心\",\"未佩戴安全帽\",\"机械违规作业\"]', NULL, '检测到 3 项隐患：未穿反光背心、未佩戴安全帽、机械违规作业。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条及《施工现场临时用电安全技术规范》（JGJ46-2005）第3.2.2条，要求在施工现场（尤其夜间、雾天、临边、交通通道等区域）作业人员必须穿戴符合GB20653-2022标准的橙色或黄色反光背心；  \n风险等级：中风险（易导致车辆碰撞、机械误伤、高处坠落时难以被及时发现）；  \n整改建议：立即停止作业，配发合规反光背心并确认穿戴到位后方可复工；  \n处理方法：对未穿戴人员进行安全教育并记录，首次违规予以口头警告，重复违规按项目安全管理制度扣减绩效或暂停上岗资格；  \n预防措施：实行“进门即查”制度（门禁岗查验反光背心），将反光背心纳入个人防护用品（PPE）发放台账动态管理，每日班前会强调穿戴要求，并在危险作业区域设置语音提示与反光标识。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备，尤其在交通动线、夜间或光线不足区域作业时。”  \n风险等级：中风险（易导致车辆碰撞、机械误伤等可视性不足引发的物体打击或车辆伤害事故）  \n整改建议：立即停止作业，配发并强制穿戴符合GB 20653-2020《职业用高可视性警示服》标准的橙色/黄色反光背心（...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条：“施工单位应当向作业人员提供安全防护用具，并监督其正确使用”。  \n风险等级：高风险（易导致头部撞击、坠落物打击，引发颅脑损伤甚至死亡）。  \n整改建议：立即停止该人员施工作业，责令其佩戴合格安全帽后方可复工；对所在班组开展专项安全教育。  \n处理方法：按项目安全管理制度实施批评教育或经济处罚（如扣减当月安全绩效分）；首次违规记录在案，重复违规升级为停工学习并通报。  \n预防措施：实行“进门即查”制度（门禁处设安全帽发放与佩戴检查岗）；每日班前安全交底强调“无帽不入场、无帽不上岗”；在作业区设置语音提示与警示标识；将安全帽佩戴纳入劳务实名制考勤联动管理。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条、《建设工程安全生产管理条例》第27条及《个体防护装备配备规范》GB 39800-2020 第5.2.1条：  \n风险等级：Ⅰ级（重大风险，可致颅脑损伤、死亡）；  \n整改建议：立即停止作业，全员清点并配发符合GB 2811-2019标准的安全帽；  \n处理方法：对未佩戴人员进行现场教育+书面警告，班组长签字确认；连续两次违...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：机械违规作业\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工安全检查标准》（JGJ59-2011）第3.18.3条及《建设工程安全生产管理条例》第二十七条：  \n风险等级：高风险（易引发机械伤害、物体打击、倾覆等群死群伤事故）  \n\n整改建议：立即停止违规作业，对涉事机械停用并挂牌标识；组织专项安全评估后方可恢复使用。  \n\n处理方法：  \n① 对操作人员进行违章行为书面记录、安全再教育及考核；  \n② 由项目安全总监牵头开展机械作业全过程复盘，形成隐患闭环台账；  \n③ 涉及无证操作、酒后作业、擅自改装等严重违规的，依企业管理制度予以停工待岗或清退。  \n\n预防措施：  \n① 严格执行“十不吊”“十不操作”及机械进场验收、定期维保、每日空载试运行制度（JGJ59-2011第3.18.2条）；  \n② 推行“人机绑定+人脸识别+操作授权”智能管控系统，杜绝非授权人员上机；  \n③ 每周开展机械作业专项巡查，重点核查持证上岗、指挥信号、作业半径警戒、地基承载力等关键项。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.18.3条（起重机械）及第3.19.3条（施工机具），机械违规作业属**重大风险等级**（直接导致倾覆、挤压、物体打击等群死群伤事故）。  \n整改建议：立即停止作业，撤出危险区域人员；对操作人员资质、设备备案、专项方案、日常维保记录开展全项核查。  \n处理方法：未持有效特种作业操作证上岗的，清退并处罚；无专项施工方案或方案未审批的，停工补编...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1048, 'http://127.0.0.1:9999/files/eb18f2a166b14200b09d492620123b34_隐患2.png', 'http://127.0.0.1:9999/files/7d0cdaabb77040ef9ea0a0bc159a7550_result.jpg', '[\"0.55\"]', '14.65秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 18:07:13', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工人员个人劳动保护用品使用管理暂行规定》（建质〔2007〕255号）第五条：进入施工现场的所有人员必须正确佩戴安全帽。\n\n风险等级：高风险（易导致颅脑损伤、死亡事故，属可预见性致命风险）\n\n整改建议：立即清退未佩戴安全帽人员，暂停其当日施工作业；对责任班组开展专项安全教育并记录存档。\n\n处理方法：  \n① 首次违规：现场纠正+口头警告+安全交底再确认；  \n② 二次违规：停工学习2学时+书面检讨+班组长连带扣分；  \n③ 三次及以上或拒不改正：清退出场，并纳入分包单位信用考核。\n\n预防措施：  \n① 实行“进门即查”制度，设置门禁式安全帽佩戴自动识别闸机或专职安检岗；  \n② 安全帽统一编号、实名登记、定期检查（有无裂纹、内衬脱落、超期使用≥2.5年）；  \n③ 每日班前会强调“无帽不入场、无帽不上岗”，并将佩戴情况纳入班组安全绩效考核。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第二十七条及《个体防护装备配备规范》GB 39800-2020 第5.2.1条明确：头部防护为强制性配备要求。  \n风险等级：高风险（可能导致颅脑损伤、致死事故）  \n整改建议：立即停止该人员作业，清退出场，经安全再教育并考核合格后方可复工。  \n处理方...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1050, 'http://127.0.0.1:9999/files/a332aeea068c4d7ab50ccd81e6792d66_隐患5.png', 'http://127.0.0.1:9999/files/1381ed39148047e8a06c5d0fdf51f544_result.jpg', '[\"0.64\",\"0.61\"]', '41.50秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:39:24', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工安全检查标准》（JGJ59-2011）表3.0.5“安全管理检查评分表”第2项：进入施工现场必须佩戴安全帽。  \n风险等级：Ⅱ级（中等风险，可能导致头部撞击、坠落物打击等轻伤或重伤事故）。  \n整改建议：立即清退未佩戴安全帽人员，暂停其当日施工作业资格；对责任班组开展专项安全教育并记录存档。  \n处理方法：按项目安全管理制度实施批评教育+扣罚绩效；首次违规书面警告，重复违规停工再培训并报项目安全部备案；监理单位签发《监理通知单》（编号：AQ-TZ-XXX）限期2小时内闭环。  \n预防措施：实行“进门即查”门禁管理（配备智能安全帽识别系统或人工岗前检查）；每日班前会强调PPE佩戴要求并签字确认；在通道口、作业区设置语音提示与警示标识（GB2894-2008）；将安全帽佩戴率纳入班组月度安全考核（权重≥15%）。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条及《个体防护装备配备规范》GB 39800.1-2020 第5.2.1条明确：安全帽为施工现场强制性基本头部防护装备。\n\n风险等级：高风险（可能导致颅脑损伤、死亡，属可记录工伤事件）\n\n整改建议：立即停止该人员作业，清退出场，经安全再教育并考核...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的人员必须正确佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场出入口、基坑周边、吊装作业区等危险区域作业人员必须穿着符合GB20653规定的橙色或黄色高可视性反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或雾天辨识失效，可能引发重伤事故）\n\n整改建议：立即停止该人员相关作业，责令穿戴合格反光背心后方可复工；对当日所有在场作业人员开展反光背心佩戴情况全覆盖排查。\n\n处理方法：首次违规予以口头警告并登记；重复违规按项目《安全生产奖惩制度》扣减当月安全绩效分2–5分，并组织再教育考核；若属分包人员，同步通报其所属单位并纳入履约评价。\n\n预防措施：①实行“进门即查”制度，门禁系统联动语音提示+人工复核反光背心佩戴；②将反光背心纳入劳保用品统一采购与发放台账，每季度检查反光条衰减情况（反光系数＜300cd·lx⁻¹·m⁻²即报废）；③每日班前教育强调高风险区域（如场内运输通道、塔吊覆盖区）强制穿戴要求，并设置现场可视化警示标牌。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的人员必须佩戴安全帽，高处作业人员应穿防滑鞋、系安全带，夜间或能见度不良区域作业时，必须穿着反光背心。”  \n同时，《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012（地方强标，广泛引用）第2.2.3条明确：“在施工现场道路、基坑周边、吊装作业区、夜间施工区等危险或通行区域作业的人...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1051, 'http://127.0.0.1:9999/files/a332aeea068c4d7ab50ccd81e6792d66_隐患5.png', 'http://127.0.0.1:9999/files/e9c4aaef72134018af33112f7d252364_result.jpg', '[\"0.64\",\"0.61\"]', '36.45秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:41:50', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.1.3条；  \n风险等级：高风险（易导致颅脑损伤、死亡事故）；  \n整改建议：立即停止该人员作业，清退出场，待完成安全教育并考核合格后方可返岗；  \n处理方法：现场责令佩戴合格安全帽（符合GB2811-2019），对违规行为按项目安全管理制度予以警告或经济处罚，并在安全日志中如实记录；  \n预防措施：实行“进门即查、上岗必戴”门禁管理；开展每日班前安全喊话与安全帽佩戴专项交底；设置智能视频监控+AI识别系统自动抓拍未佩戴行为；将安全帽佩戴纳入班组安全绩效考核。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须正确佩戴安全帽”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.1.3条（地方强标，普遍引用）明确“未佩戴安全帽属严重违规行为”；同时《安全帽》GB 2811-2019 第4.1条强制规定“作业人员在可能发生头部伤害的场所必须佩戴符合标准的安全帽”。\n\n风...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场所有人员（含管理人员、作业人员、访客）在施工区域活动时，必须穿着符合要求的荧光反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械碾压、夜间或低照度环境下的误伤事故，属可预见性高发隐患）\n\n整改建议：立即停止未穿反光背心人员进入施工作业区；对当日所有进场人员开展反光背心穿戴情况全面排查。\n\n处理方法：  \n① 对首次违规者进行现场安全教育并登记备案；  \n② 对重复违规者按项目安全管理制度予以警告或停工学习；  \n③ 现场配备备用反光背心，由门禁岗统一发放、回收并登记。\n\n预防措施：  \n① 实行“无反光背心不入场”硬性门禁管控，与人脸识别/IC卡系统联动；  \n② 在工地主出入口、塔吊覆盖区、运输通道等高风险区域设置语音提示及LED警示屏；  \n③ 将反光背心穿戴纳入班前教育必查项和每日安全巡查重点内容。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012（地方强标，广泛引用）第2.2.3条明确：“在施工作业区、运输通道、基坑周边等区域活动的人员，必须穿着符合GB 20653-2022《职业用高可视性警示服》要求的橙色或黄色反光背...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1052, 'http://127.0.0.1:9999/files/a332aeea068c4d7ab50ccd81e6792d66_隐患5.png', 'http://127.0.0.1:9999/files/00c0d87dc5854324a190af1183ecd549_result.jpg', '[\"0.64\",\"0.61\"]', '31.83秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:44:51', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工安全检查标准》（JGJ59-2011）表3.0.5“安全管理检查评分表”第2项：进入施工现场必须佩戴安全帽。  \n风险等级：高风险（易导致头部撞击、坠落物打击，引发颅脑损伤甚至死亡）。  \n整改建议：立即清退未戴安全帽人员，暂停其施工作业；对责任班组开展专项安全教育并考核合格后方可复工。  \n处理方法：现场监督员当场纠正，开具《安全隐患整改通知单》（编号：AQ-HAT-001），2小时内完成闭环整改并留存影像记录；重复违规者按项目安全奖惩制度予以经济处罚或停工学习。  \n预防措施：实行“进门即查帽”门禁管理，设置智能安全帽识别摄像头；每日班前会强调PPE穿戴要求；将安全帽佩戴纳入班组日巡查与月度安全绩效考核。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条及《个体防护装备配备规范》GB 39800.1-2020 第5.2.1条明确：安全帽为施工现场强制性基本头部防护装备。  \n风险等级：高风险（可能导致颅脑损伤、死亡，属可记录工伤事件）  \n整改建议：立即停止该人员作业，清退出场，待正确佩戴合格...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条及《施工现场临时用电安全技术规范》（JGJ46-2005）第3.1.3条，要求进入施工现场的人员必须穿戴符合GB 20653-2020规定的反光警示服（含反光背心）。  \n风险等级：中风险（易导致车辆碰撞、机械伤害等可视性不足引发的事故）。  \n整改建议：立即停止作业，未穿戴者须配发并正确穿戴合格反光背心后方可入场。  \n处理方法：现场安全员当场纠正，登记违规人员信息；首次违规予以口头警告并记录在案；重复违规按《项目安全生产奖惩制度》扣减当月安全绩效分。  \n预防措施：①实行“进门即查”制度，设置门禁岗查验反光背心佩戴情况；②将反光背心纳入个人防护用品（PPE）强制发放清单，每日班前检查并签字确认；③开展“可视安全”专项教育，每季度组织反光装备辨识与应急避让实操演练。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备，尤其在交通流线区域、夜间或低照度作业区、车辆通行区等场所。”  \n风险等级：中风险（易导致车辆碰撞、机械伤害或误入危险作业区）  \n整改建议：立即停止作业，配发并强制穿戴符合GB 20653-2020《职业用高可视性警示服》标准的橙色/荧光黄反光背心（反光带...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1053, 'http://127.0.0.1:9999/files/a332aeea068c4d7ab50ccd81e6792d66_隐患5.png', 'http://127.0.0.1:9999/files/49fe073b7a71404a9104565826521566_result.jpg', '[\"0.64\",\"0.61\"]', '33.01秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:48:28', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工个人防护用品使用管理规范》（JGJ184-2009）第4.1.1条：进入施工现场的所有人员必须正确佩戴合格安全帽。  \n风险等级：Ⅱ级（中等风险，易引发头部撞击、坠落物打击致颅脑损伤，属可导致重伤或死亡的典型违章行为）。  \n整改建议：立即清退未佩戴安全帽人员，暂停其当日施工作业资格；对责任班组开展专项安全教育并记录存档。  \n处理方法：按项目安全奖惩制度扣减当事人当月安全绩效分；班组长连带考核；首次违规书面警告，重复违规停工再培训并报公司安监部门备案。  \n预防措施：实行“进门即查”门禁式管理（人脸识别+安全帽佩戴自动识别系统）；每日岗前“三查”（查衣着、查证件、查防护用品）；设置安全帽专用存放架及破损更换绿色通道；将安全帽佩戴纳入班前讲评必查项和视频监控AI智能识别重点项。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须正确佩戴安全帽”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.1.3条（引用GB 2811-2019《头部防护 安全帽》强制性要求）：安全帽须符合国家标准，且佩戴时下颌带应系紧。  \n风险等级：Ⅱ级（中等风险，可能导致头部撞击伤害，属可记录工伤事件）。 ...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》JGJ80-2016第3.0.5条及《施工现场临时用电安全技术规范》JGJ46-2005第3.1.3条（强制性条文）：进入施工现场的人员必须佩戴安全帽、穿反光背心等个体防护装备；高风险区域（如夜间、临边、交通动线、吊装区）未穿戴反光背心属Ⅱ级（中等）风险。\n\n整改建议：立即停止该人员作业，责令其穿戴符合GB 20653-2020《职业用高可视性警示服》标准的橙色或荧光黄反光背心后方可复工。\n\n处理方法：现场安全员当场纠正并登记违规行为；同一班组重复发生时，按项目《安全奖惩制度》扣减当月安全绩效分，并组织专项交底。\n\n预防措施：①将反光背心纳入入场三级教育必查项和每日班前会点名确认内容；②在工地主出入口、塔吊覆盖区、车辆通道等关键区域设置反光背心穿戴提示标识；③实行“背心领用登记+回收核销”闭环管理，确保人证对应、及时更新。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.4条：“进入施工现场的人员必须佩戴安全帽，高处作业人员应穿防滑鞋、系安全带；在施工现场通道、作业面等区域活动的人员，应穿着符合GB 20653—2006《职业用高可视性警示服》规定的反光背心或警示服。”  \n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或低照度环境下识别失效，引发物体打击或车辆伤害事故）  \n整改建议：立即停...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1054, 'http://127.0.0.1:9999/files/02f11772645e4c11904c59ccfb2d46ce_隐患1.png', 'http://127.0.0.1:9999/files/7b5cca8cd01b454b8aabacddb415a544_result.jpg', '[\"0.58\",\"0.55\",\"0.47\"]', '44.81秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:50:16', '[\"未穿反光背心\",\"未佩戴安全帽\",\"机械违规作业\"]', NULL, '检测到 3 项隐患：未穿反光背心、未佩戴安全帽、机械违规作业。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的人员必须正确佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场出入口、基坑周边、吊装作业区等危险区域作业人员必须穿着符合GB20653规定的橙色或黄色高可视性反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或雾天辨识失效，可能引发重伤事故）\n\n整改建议：立即停止该人员相关作业，责令穿戴合格反光背心后方可复工；对当日所有在场作业人员开展反光背心佩戴情况全覆盖排查。\n\n处理方法：按项目安全管理制度进行登记扣分；首次违规予以口头警告并记录；重复违规须停工再教育并纳入班组考核。\n\n预防措施：①将反光背心纳入劳保用品发放台账，实行“一人一卡、领用签字、定期更换”；②在工地出入口设置反光背心强制穿戴提示牌及自助领取点；③每日班前教育强调高风险区域（如场内运输通道、塔吊覆盖区）必须全程穿戴；④安全员采用“四不两直”方式开展随机抽查，结果与分包单位履约评价挂钩。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备，特别是在夜间、雾天、雨雪天气或临边、基坑、道路交叉区域等视线不良环境下。”  \n风险等级：中风险（易导致车辆碰撞、机械误伤、高处坠物识别滞后等事故）  \n整改建议：立即停止作业，全员配发符合GB 20653-2020《职业用高可视性警示服》标准的橙色/荧光黄...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条：“进入施工现场的所有人员必须正确佩戴安全帽”；《建设工程安全生产管理条例》第三十二条：“施工单位应当向作业人员提供安全防护用具，并监督其正确使用”。  \n风险等级：高风险（易导致头部撞击、坠落物打击，引发颅脑损伤甚至死亡）。  \n整改建议：立即停止该人员作业，责令其佩戴合格安全帽后方可复工；对现场所有人员开展安全帽佩戴情况全面排查。  \n处理方法：首次违规予以警告并记录在案；二次违规须停工接受安全再教育并考核合格；造成隐患或事故的，按企业安全管理制度追责。  \n预防措施：①实行“无帽禁入”门禁管理，入口设专人检查；②安全帽统一编号、定期检测（有效期≤30个月，冲击吸收性能≤4900N）；③每日班前教育强调头部防护要求，并纳入安全技术交底内容。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条及《个体防护装备配备规范》GB 39800.1-2020 第5.2.1条明确：安全帽为施工现场强制性基本头部防护装备。  \n风险等级：高风险（可能导致颅脑损伤、死亡，属可记录工伤事件）  \n整改建议：立即停止该人员作业，清退出场，待正确佩戴合格...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：机械违规作业\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工安全检查标准》（JGJ59-2011）第3.1.3条、第3.18节（起重机械与吊装作业）及《建设工程安全生产管理条例》第二十七条，机械违规作业属**重大风险等级**（可能导致群死群伤或设备倾覆）。  \n\n**整改建议**：立即停止违规机械作业，撤出作业人员，对涉事设备进行停用封存；组织专项安全评估后方可恢复。  \n\n**处理方法**：  \n- 对操作人员开展违章行为复盘教育并记录在案；  \n- 依据《建筑施工特种作业人员管理规定》（建办质〔2019〕46号）核查操作资格，无证或证件过期者一律清退；  \n- 对项目负责人、安全员依《安全生产法》第九十四条追责。  \n\n**预防措施**：  \n- 实施“一机一档”动态管理，每日作业前执行“三查”（查资质、查工况、查交底）；  \n- 安装智能监控系统（如力矩限制器、高度限位器、视频黑匣子），接入智慧工地平台实时预警；  \n- 每月开展机械专项隐患排查+实操考核，留存影像及签字记录。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.1.3条（机械设备）、第3.17条（塔式起重机、施工升降机等专项检查）及《施工现场机械设备检查技术规范》JGJ 160-2016 第4.1.1条、第5.2.3条：  \n- **风险等级**：高风险（易引发倾覆、挤压、物体打击、机械伤害等群死群伤事故）；  \n- **整改建议**：立即停止违规作业，撤出作业人员，对设备进行停机封存；  \n- ...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1055, 'http://127.0.0.1:9999/files/02f11772645e4c11904c59ccfb2d46ce_隐患1.png', 'http://127.0.0.1:9999/files/45513bd164454bf2b6bbab24150f69d1_result.jpg', '[\"0.58\",\"0.55\",\"0.47\"]', '47.74秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:53:36', '[\"未穿反光背心\",\"未佩戴安全帽\",\"机械违规作业\"]', NULL, '检测到 3 项隐患：未穿反光背心、未佩戴安全帽、机械违规作业。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条及《施工现场临时用电安全技术规范》（JGJ46-2005）第3.1.3条，要求进入施工现场的人员必须穿戴符合GB 20653-2022《职业用高可视性警示服》标准的反光背心；  \n风险等级：中风险（易导致车辆碰撞、机械误伤等可预见性伤害）；  \n整改建议：立即停止无反光背心人员进入施工作业区或交通流线区域，补发合规反光背心并登记领用；  \n处理方法：对当事人进行现场安全再教育并记录，首次违规予以口头警告，重复违规按项目安全奖惩制度扣减安全积分或绩效；  \n预防措施：实行“进门即查”准入管理（门禁系统联动反光背心识别或人工岗前检查），将反光背心纳入班前会“三宝”（安全帽、安全带、反光背心）必查项，并在高风险作业区（如场内运输通道、夜间施工区、吊装警戒区）设置醒目的反光标识提示牌。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的所有人员必须佩戴安全帽，并在存在车辆通行、夜间或能见度不良区域作业时，必须穿着符合GB 20653—2006《职业用高可视性警示服》规定的反光背心（或高可视性服装）。”  \n风险等级：中风险（易导致车辆碰撞、机械伤害、误入危险作业区等事故）  \n整改建议：立即停止相关区域作业，对未穿戴人员进行现场纠正并登记...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工个人防护用品使用管理规范》（JGJ184-2009）第4.1.1条：  \n风险等级：高风险（易导致颅脑损伤，属可致死性违章行为）。  \n整改建议：立即停止作业，清退未佩戴安全帽人员，全员复核入场教育与PPE领用记录。  \n处理方法：对违章人员按项目安全管理制度进行批评教育+书面检讨+停工再培训；班组长连带扣分；同一班组重复发生须升级为警告处分。  \n预防措施：①实行“进门即查、上岗必戴”门禁式管理（设置智能安全帽识别通道）；②每日班前会强调并抽查佩戴情况；③安全帽统一编号绑定责任人，实行“一帽一档”溯源管理；④在作业区入口、危险源附近设置语音提示与警示标识。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.1.3条（文明施工检查评定保证项目）及《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.2.1条：进入施工现场的所有人员必须佩戴符合GB 2811-2019《头部防护 安全帽》要求的安全帽。  \n风险等级：高风险（属“人的不安全行为”中直接导致物体打击致死/重伤的A类风险）。  \n整改建议：立即停止该人员...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：机械违规作业\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工安全检查标准》（JGJ59-2011）第3.1.3条、第3.18节（起重机械与吊装作业）及《建设工程安全生产管理条例》第二十七条，机械违规作业属**重大风险等级**（可能导致群死群伤或设备倾覆）。  \n\n**整改建议**：立即停止违规机械作业，撤出作业人员，对涉事设备停用并挂牌标识；组织专项安全评估后方可恢复。  \n\n**处理方法**：  \n① 对操作人员开展违章行为“四不放过”处理（原因未查清不放过、责任人未处理不放过、整改措施未落实不放过、有关人员未受教育不放过）；  \n② 依据《建筑施工特种作业人员管理规定》（建质〔2008〕75号）核查操作证有效性，无证或超范围作业者一律清退；  \n③ 对设备进行第三方检测，重点核查限位器、力矩限制器、钢丝绳磨损及基础承载力。  \n\n**预防措施**：  \n① 实施“一机一档”动态管理，每日作业前执行“三查”（查证件、查交底、查设备状态）；  \n② 推行可视化交底+AI行为识别监控系统，对吊装半径内站人、斜拉斜吊等高危动作实时预警；  \n③ 每季度开展机械作业“双随机”抽查（随机人员、随机工况），结果纳入分包单位履约评价。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.17.3条（起重机械）及第3.18.3条（施工机具），机械违规作业属**重大风险等级**（可能导致群死群伤或设备倾覆）。  \n整改建议：立即停止作业，撤出危险区域人员，对操作人员资质、设备备案、专项方案及日常维保记录进行全项核查。  \n处理方法：对无证操作、超载运行、未按方案吊装、安全限位失效等行为，依据JGJ 59-2011第3.17.4...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1056, 'http://127.0.0.1:9999/files/45ecb705457f4942813469826d090e8e_隐患6.png', 'http://127.0.0.1:9999/files/ff0e325fa8f2480293508d588ef893f8_result.jpg', '[\"0.48\",\"0.22\"]', '27.70秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 20:55:04', '[\"未穿反光背心\",\"未佩戴安全帽\"]', NULL, '检测到 2 项隐患：未穿反光背心、未佩戴安全帽。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条及《施工现场临时用电安全技术规范》（JGJ46-2005）第3.1.3条，要求在施工现场（尤其夜间、雾天、临边、交通通道等区域）作业人员必须穿戴符合GB 20653-2006标准的橙红色Ⅱ级反光背心；未穿戴属一般风险（风险等级：Ⅱ级）。  \n整改建议：立即停止该人员现场作业，配发合规反光背心并经班组长确认穿戴后方可复工。  \n处理方法：对当事人进行安全再教育并记录在案；班组长当日开展专项检查，覆盖全部在岗人员。  \n预防措施：将反光背心纳入入场三级安全教育必查项；设置门禁式智能识别岗（如AI摄像头自动预警未穿戴行为）；实行“背心领用登记+离场回收”闭环管理。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备，尤其在交通流线区域、夜间或低照度作业区、车辆通行区等场所。”  \n风险等级：中风险（易导致车辆碰撞、机械伤害或误入危险作业区）  \n整改建议：立即停止作业，配发并强制穿戴符合GB 20653-2020《职业用高可视性警示服》标准的橙色/荧光黄反光背心（反光带...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工人员个人劳动保护用品使用管理暂行规定》（建质〔2007〕255号）第五条：进入施工现场的所有人员必须正确佩戴安全帽。  \n风险等级：高风险（易导致颅脑损伤，属可致死性违章行为）。  \n整改建议：立即清退未佩戴安全帽人员，暂停其当日施工作业资格；对责任班组开展专项安全教育并记录存档。  \n处理方法：依据《建设工程安全生产管理条例》第六十二条，对施工单位处1万元以上3万元以下罚款；对直接责任人按企业安全管理制度予以警告或经济处罚；首次违规者须完成8学时安全再培训并考核合格后方可复工。  \n预防措施：实行“进门即查”门禁管理（人脸识别+安全帽佩戴自动识别系统）；每日班前会强制检查并签字确认；设置安全帽专用存放架与领用登记台账；将安全帽佩戴纳入班组安全绩效考核（权重不低于20%）。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.1.3条（文明施工保证项目）及《建设工程安全生产管理条例》第三十二条，未佩戴安全帽属**高风险违章行为**（风险等级：Ⅰ级/重大风险）。  \n整改建议：立即停止作业，全员清点并配发符合GB 2811-2019《头部防护 安全帽》标准的合格安全帽。  \n处理方法：对违规人员进行安全再教育并记录在案；班组长、安全员负连带责任，按项目奖惩制度处罚...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1057, 'http://127.0.0.1:9999/files/45ecb705457f4942813469826d090e8e_隐患6.png', 'http://127.0.0.1:9999/files/570b20b1ee2246a8a51e9ce5d28aac00_result.jpg', '[\"0.48\",\"0.22\"]', '32.14秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-01 21:01:21', '[\"未穿反光背心\",\"未佩戴安全帽\"]', NULL, '检测到 2 项隐患：未穿反光背心、未佩戴安全帽。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条及《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：施工现场所有进入危险区域（含基坑周边、吊装作业区、运输通道、夜间或能见度不良区域）的人员必须穿戴符合GB 20653-2022规定的橙红色反光背心（Ⅱ级反光材料，反光面积≥400cm²）。  \n风险等级：中风险（易导致车辆碰撞、机械误伤、高处坠物识别延迟等）  \n整改建议：立即停止该人员相关作业，配发合规反光背心并确认穿戴后方可复工。  \n处理方法：对当事人进行安全再教育并记录；班组长当日组织全员反光装备专项检查；安全部门开具隐患整改通知单（24小时内闭环）。  \n预防措施：①将反光背心纳入入场三级教育必查项和每日班前交底内容；②在工地主出入口、塔吊覆盖区、施工电梯口设置反光背心强制穿戴提示牌；③实行“背心+定位手环”双识别管理，未佩戴者门禁系统自动报警。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的作业人员必须佩戴安全帽、穿反光背心等个体防护装备，尤其在交通流线区域、夜间或能见度不良环境下作业时，反光背心为强制性配备。”  \n风险等级：中风险（可能引发车辆碰撞、机械误伤等事故，属可预见性人身伤害风险）  \n整改建议：立即停止相关区域作业，全员配发符合GB 20653-2020《职业用高可视性警示服》标...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工人员个人劳动保护用品使用管理暂行规定》（建质〔2007〕255号）第四条：进入施工现场的所有人员必须佩戴符合GB2811-2019标准的安全帽。  \n风险等级：高风险（易导致颅脑损伤，属可致死性违章行为）。  \n整改建议：立即清退未佩戴安全帽人员，暂停其施工作业；对责任班组开展专项安全教育并记录存档。  \n处理方法：首次违规，责令当场纠正并记入安全日志；重复违规，按项目安全奖惩制度扣减绩效，并组织重新考核合格后方可复工。  \n预防措施：实行“进门即查”门禁管理（联动人脸识别+安全帽佩戴自动识别系统）；每日班前会强调PPE强制要求；在施工区入口、通道、作业面设置醒目的安全帽佩戴警示标识及反光镜自检点。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.1.1条（强制性条文），以及《建筑施工安全检查标准》JGJ 59-2011 表B.1.1（文明施工检查评定表）第2项明确要求：“进入施工现场人员必须正确佩戴安全帽”。\n\n风险等级：高风险（属A类违章，可直接导致头部撞击伤害，致死致残率高）...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1058, 'http://127.0.0.1:9999/files/ed3d9c1029a34915bbba102aee7f2602_隐患2.png', 'http://127.0.0.1:9999/files/7d23a14d6f7140de8e3c7fa5981e5536_result.jpg', '[\"0.55\"]', '16.02秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-02 23:53:26', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工个人防护用品使用管理规范》（JGJ184-2009）第4.1.1条：进入施工现场所有人员必须佩戴符合GB2811-2019标准的安全帽。  \n风险等级：高风险（易导致颅脑损伤，属可致死性违章行为）。  \n整改建议：立即停止该人员作业，清退出场，待完成安全教育并考核合格后方可复工；同步排查同班组其他人员佩戴情况。  \n处理方法：依据《建筑施工安全检查标准》（JGJ59-2011）第3.1.3条，对违章人员按项目安全管理制度予以警告或经济处罚；班组长负连带责任，记录在案并纳入月度安全绩效考核。  \n预防措施：实行“进门登记+智能门禁人脸识别+安全帽佩戴自动识别”双控机制；每日班前会强制检查并签字确认；设置安全帽专用存放架及破损更换绿色通道；开展典型事故案例警示教育（如坠落物击中未戴帽人员致死事件），每季度复训考核。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.1.3条（文明施工保证项目）及《建设工程安全生产管理条例》第三十二条，未佩戴安全帽属**高风险违章行为**（风险等级：Ⅰ级/重大风险）。  \n整改建议：立即停止作业，全员清点并配发符合GB 2811-2019《头部防护 安全帽》标准的合格安全帽。  \n处理方法：对违规人员进行安全再教育并记录；班组长及以上管理人员未监督到位的，依企业安全责任...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1059, 'http://127.0.0.1:9999/files/6e7f021d6c934cd98f781f6589e3d736_隐患2.png', 'http://127.0.0.1:9999/files/58cdb200000f4c1bb2c17fcacecb544a_result.jpg', '[\"0.55\"]', '51.64秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-03 00:05:18', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.1条、《建设工程安全生产管理条例》第二十七条及《建筑施工个人防护用品使用管理规范》（JGJ184-2009）第4.1.1条：进入施工现场的所有人员必须正确佩戴合格安全帽。  \n风险等级：高风险（易导致颅脑损伤，属A类可致死违章）。  \n整改建议：立即停止该人员施工作业，清退出场，经安全再教育并考核合格后方可复工。  \n处理方法：现场责令纠正；对当事人及班组长进行书面通报批评；按企业安全管理制度扣减当月安全绩效；同一班组累计2人次未戴帽，暂停该班组作业资格。  \n预防措施：实行“进门即查帽”门禁管理；推行安全帽内置芯片考勤+智能识别监控；每日班前会开展“帽带系紧、帽衬完好、无破损变形”三查；设置安全帽专用存放架及更换登记台账。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须正确佩戴安全帽”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》DB11/945-2012 第2.1.3条（地方强标，普遍引用）明确“未佩戴安全帽属严重违规行为”；同时《安全帽》GB 2811-2019 第4.1条强制规定“作业人员在可能发生头部伤害的场所必须佩戴符合标准的安全帽”。\n\n风...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1060, 'http://127.0.0.1:9999/files/de585538119a4d99aa79a12106675bf5_隐患2.png', 'http://127.0.0.1:9999/files/4a2d5afd03ff47c6a3c68ecb2e5b518d_result.jpg', '[\"0.55\"]', '17.02秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-03 00:15:07', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.1.3条；  \n风险等级：Ⅱ级（中等风险，存在头部撞击、坠落物打击致轻伤或颅脑损伤可能）；  \n整改建议：立即停止该人员作业，清退至安全区域，经安全教育考核合格后方可返岗；  \n处理方法：现场责令纠正，登记违章记录，按项目安全管理制度予以警告或经济处罚（首次违章扣罚200元，重复发生加倍）；  \n预防措施：实行“进门即戴帽”门禁管控，设置安全帽自动识别摄像系统；班前教育强制核查佩戴情况；安全员每日开展3次巡回抽查并留痕；在临边、吊装、垂直运输等高风险区域增设语音提示与LED警示标识。\n\n    📖 依据：依据《建筑施工安全检查标准》JGJ 59-2011 第3.1.3条（文明施工保证项目）及《建设工程安全生产管理条例》第三十二条，未佩戴安全帽属**高风险违章行为**（风险等级：Ⅰ级/重大风险）。  \n整改建议：立即停止作业，全员清点并配发符合GB 2811-2019《头部防护 安全帽》标准的合格安全帽。  \n处理方法：对涉事人员进行安全再教育并记录；班组长及以上管理人员未监督到位的，按企业安全责任...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1061, 'http://127.0.0.1:9999/files/83fa9132590c483c9470c28f587458af_隐患2.png', 'http://127.0.0.1:9999/files/736fe0abe5fd49a88240fd57a27e009f_隐患1.png', '[\"0.55\"]', '270.76秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-25 17:19:16', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.1.3条；  \n风险等级：高风险（易导致颅脑损伤、死亡事故）；  \n整改建议：立即停止该人员作业，清退出场，待完成安全教育并考核合格后方可返岗；  \n处理方法：现场责令佩戴合格安全帽（符合GB2811-2019），对违规行为按项目安全管理制度予以警告或经济处罚，并在安全日志中如实记录；  \n预防措施：实行“进门即查、上岗必戴”门禁管理；开展每日班前安全喊话与安全帽佩戴专项检查；设置人脸识别+安全帽识别智能监控系统；将安全帽佩戴纳入班组安全绩效考核。\n\n    📖 依据：【建筑施工安全规范】针对\'未佩戴安全帽 建筑安全规范 JGJ GB 风险要求\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1062, 'http://127.0.0.1:9999/files/736fe0abe5fd49a88240fd57a27e009f_隐患1.png', 'http://127.0.0.1:9999/files/736fe0abe5fd49a88240fd57a27e009f_隐患1.png', '[\"0.58\",\"0.55\",\"0.47\"]', '526.05秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-25 17:22:13', '[\"未穿反光背心\",\"未佩戴安全帽\",\"机械违规作业\"]', NULL, '检测到 3 项隐患：未穿反光背心、未佩戴安全帽、机械违规作业。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    【建筑施工安全规范】针对\'未穿反光背心 整改措施 处理方法 预防措施 建筑施工安全\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。\n\n    📖 依据：【建筑施工安全规范】针对\'未穿反光背心 建筑安全规范 JGJ GB 风险要求\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    【建筑施工安全规范】针对\'未佩戴安全帽 整改措施 处理方法 预防措施 建筑施工安全\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。\n\n    📖 依据：【建筑施工安全规范】针对\'未佩戴安全帽 建筑安全规范 JGJ GB 风险要求\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：机械违规作业\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    【建筑施工安全规范】针对\'机械违规作业 整改措施 处理方法 预防措施 建筑施工安全\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。\n\n    📖 依据：【建筑施工安全规范】针对\'机械违规作业 建筑安全规范 JGJ GB 风险要求\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1063, 'http://127.0.0.1:9999/files/f3a45ac598764cfe8c961e08154301a5_隐患2.png', 'http://127.0.0.1:9999/files/f20b0c3337294663b954314be2ec30f8_result.jpg', '[\"0.55\"]', '465.71秒', 0.50, 'construction_safety.pt', 'lvanna', '2026-08-25 17:49:07', '[\"未佩戴安全帽\"]', NULL, '【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    【建筑施工安全规范】针对\'未佩戴安全帽 整改措施 处理方法 预防措施 建筑施工安全\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。\n\n    📖 依据：【建筑施工安全规范】针对\'未佩戴安全帽 建筑安全规范 JGJ GB 风险要求\'隐患，请参照JGJ59-2011《建筑施工安全检查标准》执行。要求：立即整改、加强安全教育、落实责任制、定期检查。...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1064, 'http://127.0.0.1:9999/files/cfeb8cf9a11d469f8b993561abda1abe_vXZuTVmmJzybc0ef85422c580bbcd27786aeb0614823.jpg', 'http://127.0.0.1:9999/files/8ddc3186edaf404993f4fd9b43b6bd39_result.jpg', '[\"0.55\",\"0.5\"]', '43.97秒', 0.50, 'construction_safety.pt', 'fanshihao', '2026/8/26 10:31:55', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.1.3条；  \n风险等级：高风险（易导致颅脑损伤、死亡事故）；  \n整改建议：立即停止该人员作业，清退出场，待完成安全教育并考核合格后方可返岗；  \n处理方法：现场责令佩戴合格安全帽（符合GB2811-2019），对违规行为按项目安全管理制度予以警告或经济处罚，并在安全日志中如实记录；  \n预防措施：实行“进门即查、上岗必戴”门禁管理；开展每日班前安全喊话与安全帽佩戴专项检查；设置人脸识别+安全帽识别智能监控系统；将安全帽佩戴纳入班组安全绩效考核。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条及《个体防护装备配备规范》GB 39800.1-2020 第5.2.1条明确：安全帽为施工现场强制性基本头部防护装备。  \n风险等级：高风险（可能导致颅脑损伤、死亡，属可记录工伤事件）  \n整改建议：立即停止该人员作业，清退出场，待正确佩戴合格...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的人员必须正确佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场出入口、基坑周边、吊装作业区等危险区域作业人员必须穿着符合GB20653规定的橙色或黄色高可视性反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或雾天辨识失效，可能引发重伤事故）\n\n整改建议：立即停止该人员相关作业，责令穿戴合格反光背心后方可复工；对当日所有在场作业人员开展反光背心佩戴情况全覆盖排查。\n\n处理方法：首次违规予以口头警告并登记；重复违规按项目《安全生产奖惩制度》扣减当月安全绩效分2–5分，并组织再教育考核；若属分包人员，同步通报其所属单位并纳入履约评价。\n\n预防措施：①实行“进门即查”制度，门禁系统联动语音提示+人工复核反光背心佩戴；②将反光背心纳入劳保用品统一采购与发放台账，每季度检查反光条衰减情况（反光系数＜300cd·lx⁻¹·m⁻²即报废）；③每日班前教育强调高风险区域（如场内运输通道、塔吊覆盖区）强制着装要求，并设专职安全员流动巡查。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的所有人员必须佩戴安全帽，并在临边、洞口、高处、夜间或能见度不良区域作业时，必须穿着符合GB 20653—2006《职业用高可视性警示服》规定的反光背心（或反光工作服）。”  \n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间失察等事故，属可预见性人为防护缺失）  \n整改建议：立即停止相关区域作业，全员核查反...\n\n    请按时完成整改并上传复检照片！');
INSERT INTO `imgrecords` VALUES (1065, 'http://127.0.0.1:9999/files/154dbe2fb5f6447ea9408698e4b4cc1a_1wedlniu6yEqc0ef85422c580bbcd27786aeb0614823.jpg', 'http://127.0.0.1:9999/files/1ea5d9700eb846eda7976a5369a5e114_result.jpg', '[\"0.55\",\"0.5\"]', '41.77秒', 0.50, 'construction_safety.pt', 'qihongyuan', '2026/8/26 11:13:42', '[\"未佩戴安全帽\",\"未穿反光背心\"]', NULL, '检测到 2 项隐患：未佩戴安全帽、未穿反光背心。\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未佩戴安全帽\n    ⚠️ 风险等级：重大隐患\n    👤 责任人员：项目经理+监理总监+施工班组\n    ⏱️ 整改时限：2小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.1.1条、《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.1.3条；  \n风险等级：高风险（易导致颅脑损伤、死亡事故）；  \n整改建议：立即停止该人员作业，清退出场，待完成安全教育并考核合格后方可返岗；  \n处理方法：现场责令佩戴合格安全帽（符合GB2811-2019），对未佩戴行为按项目安全奖惩制度予以扣款或警告；同一班组出现2人次以上，对该班组长约谈并通报批评；  \n预防措施：实行“进门即查、上岗必检”制度，设置门禁式安全帽智能识别系统；每日班前教育强调头部防护要求；在临边、吊装、交叉作业等高风险区域增设语音提示与警示标识；安全帽统一编号、专人专用、定期检查更换（使用期≤30个月，受过冲击立即报废）。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.1.1条：“进入施工现场的所有人员必须佩戴安全帽”；《建设工程安全生产管理条例》第三十二条及《个体防护装备配备规范》GB 39800.1-2020 第5.2.1条明确：安全帽为施工现场强制性基本头部防护装备。  \n风险等级：高风险（可能导致颅脑损伤、死亡，属可记录工伤事件）  \n整改建议：立即停止该人员作业，清退出场，待正确佩戴合格...\n\n    请按时完成整改并上传复检照片！\n\n---\n\n【安全隐患整改通知】\n\n    🚨 隐患类型：未穿反光背心\n    ⚠️ 风险等级：较大隐患\n    👤 责任人员：专职安全员+施工班组长\n    ⏱️ 整改时限：4小时\n\n    📋 整改建议：\n    依据《建筑施工高处作业安全技术规范》（JGJ80-2016）第3.0.5条：“进入施工现场的人员必须正确佩戴安全帽、穿反光背心等个体防护装备”；《建设工程施工现场安全防护、场容卫生及消防保卫标准》（DB11/945-2012）第2.2.3条：“施工现场出入口、基坑周边、吊装作业区等危险区域作业人员必须穿着符合GB20653规定的橙色或黄色高可视性反光背心”。\n\n风险等级：中风险（易导致车辆碰撞、机械误伤、夜间或雾天失察等，属可预见性人身伤害隐患）\n\n整改建议：立即停止该人员相关作业活动，责令其穿戴合规反光背心后方可复工；对当日所有进场人员开展反光背心佩戴情况全覆盖排查。\n\n处理方法：首次违规，予以现场安全教育并记录在册；重复发生，按项目《安全生产奖惩制度》扣减当月安全绩效，并组织重新参加岗前安全培训考核。\n\n预防措施：①实行“进门即查”制度，门禁系统联动语音提示+人工复核反光背心佩戴；②将反光背心纳入劳保用品统一配发台账，按人编号、定期更换（每6个月强制更新）；③每日班前会强调高风险区域（如场内运输通道、塔吊覆盖区）反光背心强制穿戴要求，并拍照留痕。\n\n    📖 依据：依据《建筑施工高处作业安全技术规范》JGJ 80-2016 第3.0.5条：“进入施工现场的所有人员必须佩戴安全帽，并在存在车辆通行、夜间或能见度不良区域作业时，必须穿着符合GB 20653—2006《职业用高可视性警示服》规定的反光背心（或高可视性服装）。”  \n风险等级：中风险（易导致车辆碰撞、机械伤害、误入危险作业区等事故）  \n整改建议：立即停止相关区域作业，对未穿戴人员进行现场纠正并登记...\n\n    请按时完成整改并上传复检照片！');

-- ----------------------------
-- Table structure for message
-- ----------------------------
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '消息类型：warning/info/success',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '消息标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '消息内容',
  `create_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建时间',
  `is_read` int(0) NULL DEFAULT 0 COMMENT '已读状态：0-未读，1-已读',
  `work_order_id` int(0) NULL DEFAULT NULL COMMENT '关联工单ID',
  `is_deleted` int(0) NULL DEFAULT 0 COMMENT '是否删除(0未删除,1已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_work_order_id`(`work_order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 334 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '消息表' ROW_FORMAT = Dynamic;

